import{_ as s,a0 as r,w as l,s as m,ao as p,I as i,x as o,a1 as t,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const k=JSON.parse('{"title":"使用 Nmon 监控 Linux 的系统性能 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Nmon 监控 Linux 的系统性能 | LCTT (201601) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Nmon 监控 Linux 的系统性能 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Nmon 监控 Linux 的系统性能 | LCTT (201601) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201601/20151223 Monitor Linux System Performance Using Nmon","title":"使用 Nmon 监控 Linux 的系统性能","tag":"201601","desc":""},"relativePath":"201601/20151223 Monitor Linux System Performance Using Nmon.md","filePath":"[post].md"}'),d={name:"201601/20151223 Monitor Linux System Performance Using Nmon.md"};function u(c,e,h,x,f,w){const n=r("Link");return l(),m("div",null,[e[13]||(e[13]=p(`<h1 id="使用-nmon-监控-linux-的系统性能" tabindex="-1">使用 Nmon 监控 Linux 的系统性能 <a class="header-anchor" href="#使用-nmon-监控-linux-的系统性能" aria-label="Permalink to “使用 Nmon 监控 Linux 的系统性能”">​</a></h1><p>Nmon（得名于 Nigel 的监控器）是IBM的员工 Nigel Griffiths 为 AIX 和 Linux 系统开发的一款计算机性能系统监控工具。Nmon 可以把操作系统的统计数据展示在屏幕上或者存储到一份数据文件里，来帮助了解计算机资源的使用情况、调整方向和系统瓶颈。这个系统基准测试工具只需要使用一条命令就能得到大量重要的性能数据。使用 Nmon 可以很轻松的监控系统的 CPU、内存、网络、硬盘、文件系统、NFS、高耗进程、资源和 IBM Power 系统的微分区的信息。</p><h3 id="nmon-安装" tabindex="-1">Nmon 安装 <a class="header-anchor" href="#nmon-安装" aria-label="Permalink to “Nmon 安装”">​</a></h3><p>Nmon 默认是存在于 Ubuntu 的仓库中的。你可以通过下面的命令安装 Nmon：</p><pre><code>sudo apt-get install nmon
</code></pre><h3 id="怎么使用nmon来监控linux的性能" tabindex="-1">怎么使用Nmon来监控Linux的性能 <a class="header-anchor" href="#怎么使用nmon来监控linux的性能" aria-label="Permalink to “怎么使用Nmon来监控Linux的性能”">​</a></h3><p>安装完成后，通过在终端输入<code>nmon</code> 命令来启动 Nmon</p><pre><code>nmon
</code></pre><p>你会看到下面的输出：</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/12/nmon-output.png" alt="nmon-output"></p><p>从上面的截图可以看到 nmon 命令行工具完全是交互式运行的，你可以使用快捷键来轻松查看对应的统计数据。你可以使用下面的 nmon 快捷键来显示不同的系统统计数据：</p><ul><li><code>q</code> : 停止并退出 Nmon</li><li><code>h</code> : 查看帮助</li><li><code>c</code> : 查看 CPU 统计数据</li><li><code>m</code> : 查看内存统计数据</li><li><code>d</code> : 查看硬盘统计数据</li><li><code>k</code> : 查看内核统计数据</li><li><code>n</code> : 查看网络统计数据</li><li><code>N</code> : 查看 NFS 统计数据</li><li><code>j</code> : 查看文件系统统计数据</li><li><code>t</code> : 查看高耗进程</li><li><code>V</code> : 查看虚拟内存统计数据</li><li><code>v</code> : 详细模式</li></ul><h3 id="核查-cpu-处理器" tabindex="-1">核查 CPU 处理器 <a class="header-anchor" href="#核查-cpu-处理器" aria-label="Permalink to “核查 CPU 处理器”">​</a></h3><p>如果你想收集关于 CPU 性能相关的统计数据，你应该按下键盘上的<code>c</code>键，之后你将会看到下面的输出：</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/12/nmon_cpu_output.png" alt="nmon_cpu_output"></p><h3 id="核查高耗进程统计数据" tabindex="-1">核查高耗进程统计数据 <a class="header-anchor" href="#核查高耗进程统计数据" aria-label="Permalink to “核查高耗进程统计数据”">​</a></h3><p>如果想收集系统正在运行的高耗进程的统计数据，按键盘上的<code>t</code>键，之后你将会看到下面的输出：</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/12/nmon_process_output.jpg" alt="nmon_process_output"></p><h3 id="核查网络统计数据" tabindex="-1">核查网络统计数据 <a class="header-anchor" href="#核查网络统计数据" aria-label="Permalink to “核查网络统计数据”">​</a></h3><p>如果想收集 Linux 系统的网络统计数据，按下<code>n</code>键，你将会看到下面输出：</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/12/nmon_network_output.png" alt="n_network_output"></p><h3 id="硬盘-i-o-图表" tabindex="-1">硬盘 I/O 图表 <a class="header-anchor" href="#硬盘-i-o-图表" aria-label="Permalink to “硬盘 I/O 图表”">​</a></h3><p>使用<code>d</code> 键获取硬盘相关的信息，你会看到下面输出：</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/12/nmon_disk_output.png" alt="nmon_disk_output"></p><h3 id="核查内核信息" tabindex="-1">核查内核信息 <a class="header-anchor" href="#核查内核信息" aria-label="Permalink to “核查内核信息”">​</a></h3><p>Nmon 一个非常重要的快捷键是<code>k</code>键，用来显示系统内核相关的概要信息。按下<code>k</code>键之后，会看到下面输出：</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/12/nmon_kernel_output.png" alt="nmon_kernel_output"></p><h3 id="获取系统信息" tabindex="-1">获取系统信息 <a class="header-anchor" href="#获取系统信息" aria-label="Permalink to “获取系统信息”">​</a></h3><p>对每个系统管理员来说一个非常有用的快捷键是<code>r</code>键，可以用来显示计算机的系统结构、操作系统版本号和 CPU 等不同资源的信息。按下<code>r</code>键之后会看到下面输出：</p><p><img src="https://www.maketecheasier.com/assets/uploads/2015/12/nmon_system_output.png" alt="nmon_system_output"></p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>还有许多其他的工具做的和 Nmon 同样的工作，不过 Nmon 对一个 Linux 新手来说还是很友好的。如果你有什么问题，尽管评论。</p><hr>`,33)),i("p",null,[e[1]||(e[1]=o("via: ",-1)),t(n,{href:"https://www.maketecheasier.com/monitor-linux-system-performance/"},{default:a(()=>[...e[0]||(e[0]=[o("https://www.maketecheasier.com/monitor-linux-system-performance/",-1)])]),_:1})]),i("p",null,[e[5]||(e[5]=o("作者：",-1)),t(n,{href:"https://www.maketecheasier.com/author/hiteshjethva/"},{default:a(()=>[...e[2]||(e[2]=[o("Hitesh Jethva",-1)])]),_:1}),e[6]||(e[6]=o(" 译者：",-1)),t(n,{href:"https://github.com/sonofelice"},{default:a(()=>[...e[3]||(e[3]=[o("sonofelice",-1)])]),_:1}),e[7]||(e[7]=o(" 校对：",-1)),t(n,{href:"https://github.com/wxy"},{default:a(()=>[...e[4]||(e[4]=[o("wxy",-1)])]),_:1})]),i("p",null,[e[10]||(e[10]=o("本文由 ",-1)),t(n,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...e[8]||(e[8]=[o("LCTT",-1)])]),_:1}),e[11]||(e[11]=o(" 原创编译，",-1)),t(n,{href:"https://linux.cn/"},{default:a(()=>[...e[9]||(e[9]=[o("Linux中国",-1)])]),_:1}),e[12]||(e[12]=o(" 荣誉推出",-1))])])}const g=s(d,[["render",u]]);export{k as __pageData,g as default};
